#!/usr/bin/env python3
"""Writes ../docs/03-pinmap.md from pinmap.json (STM32H743ZIT6 LQFP-144 allocation)."""
import json, os
H = os.path.dirname(os.path.abspath(__file__))
r = json.load(open(os.path.join(H, "pinmap.json")))
groups = {}
for k, v in r.items():
    g = k.split("_")[0] if k.split("_")[0] in ("QSPI", "ETH", "LCD", "USB", "CAN", "RS485", "CON", "I2C", "TOUCH", "SPI", "ADC", "LED") else "CONTROL"
    groups.setdefault(g, []).append((k, v))
out = ["# 3. STM32H743ZIT6 pin map (LQFP-144)", "",
       "Generated by `hardware/gen_pinmap_doc.py` from `hardware/pinmap.json` (made by `pinmap.py`). Every alternate function was matched against",
       "ST's open pin data for STM32H743ZITx (`h743zit_af.json`); the generator asserts it again at build time. Not used: PA13/PA14 (SWD), PH0/PH1 (HSE), PC14/PC15 (LSE), PA11/PA12 (USB).", "",
       "Active-low control nets (reset/boot state = pin high-Z with a pull-up = everything OFF): `MPPT_NEN`, `LOAD_NEN`, `INV_NEN`.", ""]
for g, items in groups.items():
    out += [f"## {g}", "", "| Signal | Pin | LQFP-144 | Function |", "|---|---|---|---|"]
    out += [f"| {k} | {v['pin']} | {v['lqfp']} | {v['signal']} |" for k, v in items]
    out.append("")
open(os.path.join(H, "..", "docs", "03-pinmap.md"), "w").write("\n".join(out))
print("docs/03-pinmap.md written,", len(r), "signals")
